import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  inOutEnvelope,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 8;

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

const Wordmark: React.FC<{ delay?: number }> = ({ delay = 0 }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const p = springIn(frame, vfps, delay, "GENTLE");
  const ty = interpolate(p, [0, 1], [-8, 0]);
  return (
    <div
      style={{
        position: "absolute",
        left: 180,
        top: 160,
        opacity: p,
        transform: `translateY(${ty}px)`,
      }}
    >
      <Img
        src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
        style={{ height: 110, width: "auto" }}
      />
    </div>
  );
};

// =============================================================
// SCENE 1 — "Three of the nine biggest AI automation channels on YouTube
//            just tripled their view to subscriber ratio."
// 00:00:00:02 - 00:00:05:06  → ~5s @ 25fps = ~127 frames
// =============================================================
const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const titleIn = springIn(frame, vfps, 2, "SNAPPY");
  const gridIn = springIn(frame, vfps, 14, "LIQUID");
