  const tiles = Array.from({ length: 9 });

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, fontFamily: "Inter, sans-serif" }}>
      <Background />
      <Wordmark delay={0} />

      {/* Headline column - off-center left */}
