      </div>

      {/* 3x3 grid of channel tiles - right side */}
      <div
        style={{
          position: "absolute",
          right: 260,
          top: 1100,
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: 36,
          width: 1400,
          opacity: gridIn,
          transform: `translateY(${interpolate(gridIn, [0, 1], [40, 0])}px)`,
        }}
