        {tiles.map((_, i) => {
          const isHighlight = i === 0 || i === 4 || i === 7;
          const itemIn = staggeredSpring(frame, vfps, i, 18, 4, "ELASTIC");
          const tripleProgress = isHighlight ? tripleIn : 0;
