                border: `1px solid ${isHighlight ? COLORS.orange : COLORS.border}`,
                borderRadius: 18,
                opacity: itemIn,
                transform: `scale(${scale * highlightScale})`,
                display: "flex",
                flexDirection: "column",
                justifyContent: "space-between",
                padding: 28,
                boxShadow: isHighlight
                  ? `0 0 60px rgba(248,102,6,${0.3 * tripleProgress})`
