// =============================================================
// MAIN COMPOSITION
// Timestamps (25fps):
//   S1: 00:00.02 - 00:05.06   →   2 → 131  = 129 frames
//   S2: 00:05.13 - 00:08.13   → 138 → 213  = 75 frames
//   S3: 00:09.00 - 00:16.01   → 225 → 401  = 178 frames
//   S4: 00:16.01 - 00:23.17   → 401 → 592  = 192 frames
//   S5: 00:23.17 - 00:25.07   → 592 → 632  = 40 frames
// =============================================================

// Frame counts per scene
const S1_LEN = 129;
const S2_LEN = 75;
const S3_LEN = 178;
const S4_LEN = 192;
const S5_LEN = 40;

// Inter-scene gaps (in frames, at 25fps)
// gap between S1 end (131) and S2 start (138) = 7 frames
// gap between S2 end (213) and S3 start (225) = 12 frames
// no gap between S3/S4 (401)
// no gap between S4/S5 (592)
const GAP_1_2 = 7;
const GAP_2_3 = 12;

const INTRO = 2;
const OUTRO = 25;

export const durationInFrames =
  INTRO +
  S1_LEN +
  GAP_1_2 +
  S2_LEN +
  GAP_2_3 +
  S3_LEN +
  S4_LEN +
  S5_LEN +
  OUTRO;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black - 2 frames to align with 00:00:00:02 start */}
      <TransitionSeries.Sequence durationInFrames={INTRO}>
        <BlackScreen />
      </TransitionSeries.Sequence>

      {/* Scene 1 */}
      <TransitionSeries.Sequence durationInFrames={S1_LEN}>
        <Scene1 />
      </TransitionSeries.Sequence>

      {/* gap before S2 */}
      <TransitionSeries.Sequence durationInFrames={GAP_1_2}>
        <BlackScreen />
      </TransitionSeries.Sequence>

      {/* Scene 2 */}
      <TransitionSeries.Sequence durationInFrames={S2_LEN}>
        <Scene2 />
      </TransitionSeries.Sequence>

      {/* gap before S3 */}
      <TransitionSeries.Sequence durationInFrames={GAP_2_3}>
        <BlackScreen />
      </TransitionSeries.Sequence>

      {/* Scene 3 */}
      <TransitionSeries.Sequence durationInFrames={S3_LEN}>
        <Scene3 />
      </TransitionSeries.Sequence>

      {/* Scene 4 - direct cut */}
      <TransitionSeries.Sequence durationInFrames={S4_LEN}>
        <Scene4 />
      </TransitionSeries.Sequence>

      {/* Scene 5 - direct cut */}
      <TransitionSeries.Sequence durationInFrames={S5_LEN}>
        <Scene5 />
      </TransitionSeries.Sequence>

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={OUTRO}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
